package validate

import "strings"

// IsEmail is the exported public API.
func IsEmail(s string) bool {
	return hasSingleAt(s)
}

// hasSingleAt is an unexported helper (implementation detail).
func hasSingleAt(s string) bool {
	i := strings.Index(s, "@")
	if i <= 0 || i == len(s)-1 {        // need text before and after @
		return false
	}
	return strings.Count(s, "@") == 1   // exactly one @
}

package counter

// Counter is exported; its internal state is not.
type Counter struct {
	n int // unexported: hidden from other packages
}

// Inc increments the counter (pointer receiver to mutate).
func (c *Counter) Inc() {
	c.n++
}

// Value exposes the current count read-only.
func (c *Counter) Value() int {
	return c.n
}
